/** The version of Kettu the web client was built with, set by its build. */
declare const __KETTU_VERSION__: string
/** The hosted build, which signs in to a Kettu account and reaches its hosts through the relay. */
declare const __KETTU_HOSTED__: boolean
/** The account service a development build of the hosted client uses; empty for the project's. */
declare const __KETTU_ACCOUNT_URL__: string
/** The relay a development build of the hosted client uses; empty for the project's. */
declare const __KETTU_RELAY_URL__: string
